def render(context):
    exec(compile('st.header(\n    "State-wise Infrastructure Analysis"\n)\nselected_state = st.selectbox(\n    "Select State / UT",\n    sorted(df["state"].unique()),\n)\nstate_row = df.loc[\n    df["state"] == selected_state\n].iloc[0]\nstate_rate = (\n    state_row["operational"]\n    / state_row["installed_total"] * 100\n    if state_row["installed_total"] > 0\n    else 0\n)\ncol_1, col_2, col_3 = st.columns(3)\ncol_1.metric(\n    "Net Installed Chargers",\n    f"{int(state_row[\'installed_total\']):,}",\n)\ncol_2.metric(\n    "Operational Chargers",\n    f"{int(state_row[\'operational\']):,}",\n)\ncol_3.metric(\n    "Operationalization Rate",\n    f"{state_rate:.1f}%",\n)\nstate_history = long_df[\n    long_df["state"] == selected_state\n].copy()\nhistory_chart = px.bar(\n    state_history,\n    x="financial_year",\n    y="gross_installations",\n    title=(\n        f"{selected_state}: Gross Annual Installations"\n    ),\n    labels={\n        "financial_year": "Financial Year",\n        "gross_installations": "Gross Installations",\n    },\n)\nst.plotly_chart(\n    history_chart,\n    width="stretch",\n)\nst.subheader(\n    "Historical Data"\n)\nst.dataframe(\n    state_history[\n        [\n            "financial_year",\n            "gross_installations",\n        ]\n    ],\n    width="stretch",\n    hide_index=True,\n)\nst.subheader(\n    "Source-reported Totals"\n)\nst.write(\n    {\n        "Installed Total":\n            int(state_row["installed_total"]),\n\n        "Operational":\n            int(state_row["operational"]),\n\n        "Decommissioned": (\n            int(state_row["decommissioned"])\n            if "decommissioned" in df.columns\n            else "Not supplied"\n        ),\n    }\n)', __file__, 'exec'), context)
